export const holdoutQueries: HoldoutQuery[] = holdoutDocuments.flatMap((d,i) => [
 {id:`meaning-${i+1}`,query:d.query,kind:i%3===0?"semantic":i%3===1?"cross-language":"hard-negative",expected:[d.name]},
 {id:`probe-${i+1}`,query:d.probe,kind:d.kind,expected:[d.name]},
]);
// Eight independently labelled multi-document questions replace eight probes.
const comparisons: [number,number,string][] = [
[0,6,"Compare fencing tokens for stale writers with monotonic clocks for duration measurement."],
[2,7,"How do Bloom filters and Merkle trees answer different catalogue comparison questions?"],
[3,17,"How do parity recovery and content-derived blob addresses solve different storage problems?"],
[10,14,"How do generator closing and cancellation signals help release unfinished work?"],
[19,20,"Compare bootstrap median uncertainty with median absolute deviation as a spread statistic."],
[24,25,"Compare dark-frame camera calibration with the ideal geometry of an elliptical orbit."],
[26,37,"种子批次位置记录与实验数据处理来源记录，各怎样保持可追溯性？"],
[39,40,"Why must a map's chosen projection and a catalogue's serialization convention be recorded explicitly?"],
];
comparisons.forEach(([a,b,query],i) => { holdoutQueries[2*a+1]={id:`compare-${i+1}`,query,kind:"multi-document",expected:[holdoutDocuments[a].name,holdoutDocuments[b].name]}; });
holdoutQueries.push(...holdoutImages.map(([name,,,query],i)=>({id:`image-${i+1}`,query,kind:"multimodal",expected:[name],imageOnly:true})));
const absent = ["What is the Finch lease duration in milliseconds?", "Meadow 实验的第三位参与者姓名是什么？", "What is the private production database password in these documents?", "温室今年真实的年度总收入是多少？", "What medical diagnosis do the greenhouse pictures establish?", "光谱仪实验中未记录的激光器波长精确是多少？", "Give the Osprey cache's measured production latency percentile.", "种子库的真实邮寄地址和联系电话是什么？"];
holdoutQueries.push(...absent.map((query,i)=>({id:`none-${i+1}`,query,kind:"no-answer",expected:[]})));
